mapper.insert:
INSERT INTO emp05_academic
       ( emp05_academic_id, emp05_person_id, emp05_fr_ym, emp05_to_ym
       , emp05_school_name, emp05_bachelor_degree, emp05_finance_relate_yn
       , emp05_degree_credit, emp05_graduate_degree, emp05_school_location
       , emp05_note )
VALUES ( #{academicId}, #{req.personId}, #{req.frYm}, #{req.toYm}
       , #{req.schoolName}, #{req.bachelorDegree}, #{req.financeRelateYn}
       , #{req.degreeCredit}, #{req.graduateDegree}, #{req.schoolLocation}
       , #{req.note} )

mapper.update:
UPDATE emp05_academic
   SET emp05_fr_ym            = #{req.frYm}
     , emp05_to_ym            = #{req.toYm}
     , emp05_school_name      = #{req.schoolName}
     , emp05_bachelor_degree  = #{req.bachelorDegree}
     , emp05_finance_relate_yn = #{req.financeRelateYn}
     , emp05_degree_credit    = #{req.degreeCredit}
     , emp05_graduate_degree  = #{req.graduateDegree}
     , emp05_school_location  = #{req.schoolLocation}
     , emp05_note             = #{req.note}
 WHERE emp05_academic_id = #{academicId}
   AND emp05_person_id IN (
       SELECT emp01_person_id FROM emp01_person WHERE emp01_company_id = #{companyId}
   )

